using System;
using System.IO;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using PaoCaixa;
namespace PaoCaixaLegacy {
 public class Feed {public string version,path,sha512;public long size;}
 public sealed class Updates {
  public const string Version="2.0.3";public string Status="Pronto para procurar atualizações.",Downloaded;public Feed Available;
  public static Feed Parse(string yaml){if(yaml==null||yaml.Length>65536)throw new Exception("Canal inválido.");Func<string,string> field=k=>{var m=Regex.Match(yaml,"(?m)^"+k+":\\s*([^\\r\\n]+)$");return m.Success?m.Groups[1].Value.Trim().Trim('"','\''):null;};var f=new Feed{version=field("version"),path=field("path"),sha512=field("sha512")};var sz=Regex.Match(yaml,@"(?m)^\s+size:\s*(\d+)\s*$");if(sz.Success)long.TryParse(sz.Groups[1].Value,out f.size);System.Version v;if(!System.Version.TryParse(f.version,out v)||!Regex.IsMatch(f.path??"",@"^PaoCaixa-Instalador-[0-9.]+-(x86|x64)\.exe$")||f.size<1024||f.size>250*1024*1024)throw new Exception("Arquivo de atualização inválido.");byte[] hash;try{hash=Convert.FromBase64String(f.sha512);}catch{throw new Exception("Hash inválido.");}if(hash.Length!=64)throw new Exception("Hash inválido.");return f;}
  static HttpWebResponse Open(Uri uri){for(int redirects=0;redirects<8;redirects++){if(uri.Scheme!="https"||!string.IsNullOrEmpty(uri.UserInfo))throw new Exception("Atualização exige HTTPS.");var r=(HttpWebRequest)WebRequest.Create(uri);r.AllowAutoRedirect=false;r.Timeout=15000;r.ReadWriteTimeout=30000;r.UserAgent="PaoCaixa/"+Version;r.AutomaticDecompression=DecompressionMethods.GZip|DecompressionMethods.Deflate;var response=(HttpWebResponse)r.GetResponse();int status=(int)response.StatusCode;if(status>=300&&status<400){var next=new Uri(uri,response.Headers["Location"]);response.Close();uri=next;continue;}if(status!=200){response.Close();throw new Exception("Canal indisponível.");}return response;}throw new Exception("Redirecionamentos excessivos.");}
  public void Check(string channel){Status="Procurando atualização…";try{ServicePointManager.SecurityProtocol=(SecurityProtocolType)3072;using(var r=Open(new Uri(Preferences.ValidateUrl(channel)+"latest.yml")))using(var s=r.GetResponseStream())using(var m=new MemoryStream()){var buffer=new byte[4096];int n;while((n=s.Read(buffer,0,buffer.Length))>0){if(m.Length+n>65536)throw new Exception("Canal inválido.");m.Write(buffer,0,n);}var f=Parse(Encoding.UTF8.GetString(m.ToArray()));if(new System.Version(f.version)<=new System.Version(Version)){Available=null;Status="Você está usando a versão mais recente.";}else{Available=f;Status="Versão "+f.version+" disponível para baixar.";}}}catch{Available=null;Status="Sem acesso ao canal de atualizações. O caixa continua funcionando offline.";}}
  public void Download(string channel,string dir,Action<int> progress){if(Available==null)throw new Exception("Procure uma nova versão antes de baixar.");var f=Available;string folder=Path.Combine(dir,"updates-native");Directory.CreateDirectory(folder);string path=Path.Combine(folder,f.path),tmp=path+".part";Downloaded=null;Status="Baixando atualização…";
   try{using(var r=Open(new Uri(Preferences.ValidateUrl(channel)+f.path)))using(var s=r.GetResponseStream())using(var o=new FileStream(tmp,FileMode.Create,FileAccess.Write,FileShare.None)){byte[] b=new byte[65536];int n,last=-1;long size=0;while((n=s.Read(b,0,b.Length))>0){size+=n;if(size>f.size)throw new Exception("Tamanho inválido.");o.Write(b,0,n);int percent=(int)(size*100/f.size);if(percent!=last){last=percent;progress(percent);}}if(size!=f.size)throw new Exception("Download incompleto.");}
    Verify(tmp,f);if(File.Exists(path))File.Delete(path);File.Move(tmp,path);Downloaded=path;Status="Atualização pronta. Feche o caixa e instale para reiniciar.";
   }catch{if(File.Exists(tmp))File.Delete(tmp);Status="Download não concluído ou não passou na verificação. Os dados foram preservados.";throw;}
  }
  public static void Verify(string path,Feed f){using(var s=File.OpenRead(path)){if(s.Length!=f.size||s.ReadByte()!=77||s.ReadByte()!=90)throw new Exception("Instalador inválido.");s.Position=0;using(var hash=SHA512.Create()){var actual=hash.ComputeHash(s);var expected=Convert.FromBase64String(f.sha512);int diff=0;for(int i=0;i<64;i++)diff|=actual[i]^expected[i];if(diff!=0)throw new Exception("A atualização não passou na verificação.");}}}
 }
}
